$("overlay").onchange=refresh;$("latch").onchange=()=>{if(!$("latch").checked){assist.clear();event({kind:"cancel"});}};
function on(id,n,vel=.8){if(!node)return;if(active.has(id))off(id);active.set(id,n);panel.flush();send({type:"on",id,note:n,vel});highlight();}
function off(id){if(active.delete(id)){send({type:"off",id});highlight();}}
function releaseAll(){for(const id of [...active.keys()])off(id);pedal.clear();deferred.clear();}
function highlight(){for(const b of $("keys").children)b.classList.toggle("active",[...active.values()].includes(Number(b.dataset.note)));}
for(let i=0;i<keys.length;i++){const b=document.createElement("button");b.textContent=keys[i].toUpperCase();b.dataset.note=60+i;if([1,3,6,8,10].includes(i))b.className="black";b.onpointerdown=e=>{b.setPointerCapture(e.pointerId);on("p"+e.pointerId,60+i);};b.onpointerup=b.onpointercancel=b.onlostpointercapture=e=>off("p"+e.pointerId);$("keys").append(b);}
