window.addEventListener("keydown",e=>{if(e.repeat||e.ctrlKey||e.altKey||e.metaKey||/INPUT|SELECT|TEXTAREA/.test(e.target.tagName))return;const k=e.key.toLowerCase();if(shortcuts[k]){e.preventDefault();heldKeys.set(k,shortcuts[k]);event({kind:"down",id:shortcuts[k]});return;}const n=keys.indexOf(k);if(n>=0){e.preventDefault();on("k"+n,60+n);}});
