$("audio").onclick=async()=>{if(context)return;try{context=new AudioContext();for(const f of ["phrase-core.js","society-core.js","fx-core.js","instrument-core.js","performance-09.js","roam-08.js","performance-worklet-09.js"])await context.audioWorklet.addModule(f);node=new AudioWorkletNode(context,"cobalite-performance",{outputChannelCount:[2]});gain=context.createGain();gain.gain.value=panel.volume*.65;node.connect(gain).connect(context.destination);node.port.onmessage=({data:d})=>{panel.feedback(d);if(d.type==="telemetry"){for(let i=0;i<8;i++)$("voices").children[i].classList.toggle("on",d.voices[i]>.01);if(lastClock&&performance.now()-lastClock>750)resetClock();}refresh();};await context.resume();panel.changed();panel.flush();$("audio").disabled=true;$("status").textContent="Audio ready";}catch(e){$("status").textContent=e.message;if(context)await context.close();context=null;node=null;gain=null;}};
