$("midi").onclick=async()=>{try{const access=await navigator.requestMIDIAccess();function attach(){for(const input of access.inputs.values())input.onmidimessage=e=>{const [s,n,v]=e.data,k=s&240,ch=input.id+":"+(s&15),id=ch+":"+n;if(s===248){if($("clock").checked&&(!clockId||clockId===input.id)){clockId=input.id;lastClock=performance.now();const bpm=tracker.tick(e.timeStamp);if(bpm!==null)send({type:"clockTempo",bpm});}return;}if(k===144&&v){deferred.delete(id);on(id,n,v/127);}else if(k===128||(k===144&&!v)){if(pedal.get(ch)&&active.has(id))deferred.set(id,ch);else off(id);}else if(k===176&&n===64){pedal.set(ch,v>=64);if(v<64)for(const [i,c] of deferred)if(c===ch){off(i);deferred.delete(i);}}else if(k===176&&n===1)send({type:"perf",key:"wheel",value:v/127});else if(k===208)send({type:"perf",key:"pressure",value:n/127});else if(k===224)send({type:"perf",key:"bend",value:((v<<7)+n-8192)/8192});else if(k===176&&(n===120||n===123))releaseAll();};$("status").textContent=access.inputs.size+" MIDI inputs";}access.onstatechange=()=>{releaseAll();resetClock();attach();};attach();}catch(e){$("status").textContent=e.message;}};
